// Accepts webhook body shaped like:
// { "returns": [ {...records...} ], "order_summary": { total_shipped_orders, total_delivered_orders, cod_shipped_orders, prepaid_shipped_orders } (optional) }
// Also tolerates a bare array as the whole body.

const body = $input.first().json.body !== undefined ? $input.first().json.body : $input.first().json;

// ---- Run identity (v3: threaded through the whole pipeline via data_quality.run_id) ----
function generateRunId() {
  const rand = Math.random().toString(36).slice(2, 8);
  return 'rs_' + Date.now().toString(36) + '_' + rand;
}
const run_id = generateRunId();

// ---- Row-count guard (v3: prevents a huge payload from taking down the demo) ----
const MAX_ROWS = 5000;

let rawRows = [];
let orderSummary = null;
let parseError = null;

if (Array.isArray(body)) {
  rawRows = body;
} else if (body && Array.isArray(body.returns)) {
  rawRows = body.returns;
  orderSummary = body.order_summary || null;
} else {
  parseError = 'Payload must be an array of records, or an object with a "returns" array.';
}

let truncated = false;
if (!parseError && rawRows.length > MAX_ROWS) {
  truncated = true;
  rawRows = rawRows.slice(0, MAX_ROWS);
}

const ALIASES = {
  order_id: ['order_id', 'orderId', 'orderid'],
  order_date: ['order_date', 'orderDate'],
  sku: ['sku', 'SKU', 'product_sku'],
  product_name: ['product_name', 'productName', 'name'],
  product_category: ['product_category', 'category'],
  product_variant: ['product_variant', 'variant'],
  size: ['size'],
  order_value: ['order_value', 'amount', 'order_amount', 'value'],
  order_status: ['order_status', 'status'],
  journey_outcome: ['journey_outcome', 'outcome'],
  return_reason_raw: ['return_reason_raw', 'reason_text', 'reason', 'return_reason'],
  customer_comment: ['customer_comment', 'comment', 'customerComment'],
  rto_reason_raw: ['rto_reason_raw', 'rto_reason'],
  is_rto: ['is_rto', 'rto', 'isRTO'],
  payment_method: ['payment_method', 'paymentMethod', 'payment'],
  cod_flag: ['cod_flag', 'is_cod'],
  courier: ['courier', 'courier_partner', 'courierPartner'],
  pincode: ['pincode', 'pin_code', 'zip', 'zipcode'],
  shipping_zone: ['shipping_zone', 'zone'],
  delivery_attempts: ['delivery_attempts', 'attempts'],
  dispatch_delay_days: ['dispatch_delay_days'],
  delivery_delay_days: ['delivery_delay_days'],
  customer_type: ['customer_type'],
  is_first_order: ['is_first_order', 'first_order'],
  refund_amount: ['refund_amount'],
  forward_shipping_cost: ['forward_shipping_cost'],
  return_shipping_cost: ['return_shipping_cost'],
  discount_amount: ['discount_amount'],
  warehouse: ['warehouse']
};

function pick(row, field) {
  for (const key of ALIASES[field]) {
    if (row[key] !== undefined && row[key] !== null && row[key] !== '') return row[key];
  }
  return undefined;
}
function toStr(v, fallback) {
  if (v === undefined || v === null) return fallback;
  return String(v).trim();
}
function toNum(v) {
  if (v === undefined || v === null || v === '') return 0;
  const n = Number(String(v).replace(/[,\u20b9\s]/g, ''));
  return Number.isFinite(n) ? n : 0;
}
function toBool(v) {
  if (typeof v === 'boolean') return v;
  if (v === undefined || v === null) return false;
  const s = String(v).trim().toLowerCase();
  return ['true', '1', 'yes', 'y', 'rto'].includes(s);
}
function normalizePayment(v) {
  if (!v) return 'Unknown';
  const s = String(v).trim().toLowerCase();
  if (s.includes('cod') || s.includes('cash')) return 'COD';
  if (s.includes('prepaid') || s.includes('online') || s.includes('card') || s.includes('upi')) return 'Prepaid';
  return 'Unknown';
}

function deriveOutcome(row, isRto) {
  const explicit = toStr(pick(row, 'journey_outcome'), '').toLowerCase();
  if (['delivered', 'returned', 'rto', 'cancelled', 'unknown'].includes(explicit)) return explicit;

  const status = toStr(pick(row, 'order_status'), '').toLowerCase();
  if (isRto || status.includes('rto') || status.includes('return to origin') || status.includes('undelivered')) return 'rto';
  if (status.includes('cancel')) return 'cancelled';
  if (status.includes('return')) return 'returned';
  if (status.includes('deliver')) return 'delivered';
  return 'unknown';
}

const invalidReasons = {};
const records = [];

if (!parseError) {
  rawRows.forEach((row, i) => {
    if (!row || typeof row !== 'object') {
      invalidReasons['not_an_object'] = (invalidReasons['not_an_object'] || 0) + 1;
      return;
    }
    const order_id = toStr(pick(row, 'order_id'), null);
    if (!order_id) {
      invalidReasons['missing_order_id'] = (invalidReasons['missing_order_id'] || 0) + 1;
      return;
    }
    const is_rto = toBool(pick(row, 'is_rto'));
    const journey_outcome = deriveOutcome(row, is_rto);

    records.push({
      order_id,
      order_date: toStr(pick(row, 'order_date'), null),
      sku: toStr(pick(row, 'sku'), 'UNKNOWN_SKU'),
      product_name: toStr(pick(row, 'product_name'), null),
      product_category: toStr(pick(row, 'product_category'), 'UNKNOWN_CATEGORY'),
      product_variant: toStr(pick(row, 'product_variant'), null),
      size: toStr(pick(row, 'size'), 'NA'),
      order_value: toNum(pick(row, 'order_value')),
      order_status: toStr(pick(row, 'order_status'), null),
      journey_outcome,
      return_reason_raw: toStr(pick(row, 'return_reason_raw'), ''),
      customer_comment: toStr(pick(row, 'customer_comment'), ''),
      rto_reason_raw: toStr(pick(row, 'rto_reason_raw'), ''),
      is_rto,
      payment_method: normalizePayment(pick(row, 'payment_method') || (toBool(pick(row, 'cod_flag')) ? 'COD' : undefined)),
      courier: toStr(pick(row, 'courier'), 'UNKNOWN_COURIER'),
      pincode: toStr(pick(row, 'pincode'), 'UNKNOWN_PINCODE'),
      shipping_zone: toStr(pick(row, 'shipping_zone'), 'UNKNOWN_ZONE'),
      delivery_attempts: toNum(pick(row, 'delivery_attempts')),
      dispatch_delay_days: toNum(pick(row, 'dispatch_delay_days')),
      delivery_delay_days: toNum(pick(row, 'delivery_delay_days')),
      customer_type: toStr(pick(row, 'customer_type'), 'UNKNOWN'),
      is_first_order: toBool(pick(row, 'is_first_order')),
      refund_amount: pick(row, 'refund_amount') !== undefined ? toNum(pick(row, 'refund_amount')) : null,
      forward_shipping_cost: pick(row, 'forward_shipping_cost') !== undefined ? toNum(pick(row, 'forward_shipping_cost')) : null,
      return_shipping_cost: pick(row, 'return_shipping_cost') !== undefined ? toNum(pick(row, 'return_shipping_cost')) : null,
      discount_amount: pick(row, 'discount_amount') !== undefined ? toNum(pick(row, 'discount_amount')) : null,
      warehouse: toStr(pick(row, 'warehouse'), null)
    });
  });
}

const total_input = Array.isArray(rawRows) ? rawRows.length : 0;
const valid_records = records.length;
const invalid_records = total_input - valid_records;

return [{
  json: {
    records,
    order_summary: orderSummary,
    meta: {
      valid: !parseError && valid_records > 0,
      parse_error: parseError,
      total_input,
      valid_records,
      invalid_records,
      invalid_reasons: invalidReasons,
      run_id,
      truncated,
      max_rows_cap: MAX_ROWS
    }
  }
}];

const meta = $json.meta;
return [{
  json: {
    product: 'ReturnShield AI',
    error: true,
    run_id: meta.run_id,
    message: meta.parse_error || 'No usable return/RTO records found in the payload.',
    details: {
      total_input: meta.total_input,
      valid_records: meta.valid_records,
      invalid_records: meta.invalid_records,
      invalid_reasons: meta.invalid_reasons
    },
    expected_format: {
      returns: [
        {
          order_id: 'string (required)',
          sku: 'string',
          order_value: 'number',
          journey_outcome: 'delivered|returned|rto|cancelled (optional - inferred from order_status/is_rto if omitted)'
        }
      ],
      order_summary: '(optional) { total_shipped_orders, total_delivered_orders, cod_shipped_orders, prepaid_shipped_orders } - enables true rate calculations instead of within-dataset shares'
    },
    generated_at: new Date().toISOString()
  }
}];

const { records, order_summary, meta } = $json;

const TRACKED_FIELDS = [
  'order_date', 'product_category', 'size', 'return_reason_raw', 'rto_reason_raw',
  'customer_comment', 'payment_method', 'courier', 'pincode', 'shipping_zone',
  'delivery_attempts', 'refund_amount', 'forward_shipping_cost', 'return_shipping_cost'
];

const UNKNOWN_SENTINELS = new Set(['UNKNOWN', 'UNKNOWN_COURIER', 'UNKNOWN_PINCODE', 'UNKNOWN_ZONE', 'UNKNOWN_CATEGORY']);

function isPresent(v) {
  if (v === undefined || v === null || v === '') return false;
  if (typeof v === 'string' && UNKNOWN_SENTINELS.has(v)) return false;
  if (typeof v === 'number' && v === 0) return false;
  return true;
}

const fieldCompleteness = {};
TRACKED_FIELDS.forEach(f => {
  const presentCount = records.filter(r => isPresent(r[f])).length;
  fieldCompleteness[f] = records.length ? Math.round((presentCount / records.length) * 100) : 0;
});

const avgCompleteness = TRACKED_FIELDS.length
  ? Math.round(TRACKED_FIELDS.reduce((s, f) => s + fieldCompleteness[f], 0) / TRACKED_FIELDS.length)
  : 0;

let confidence = 'low';
if (records.length >= 30 && avgCompleteness >= 60) confidence = 'high';
else if (records.length >= 10 && avgCompleteness >= 35) confidence = 'medium';

const fields_largely_missing = TRACKED_FIELDS.filter(f => fieldCompleteness[f] < 20);

const data_quality = {
  run_id: meta.run_id,
  input_truncated: meta.truncated || false,
  max_rows_cap: meta.max_rows_cap,
  records_analyzed: records.length,
  invalid_records: meta.invalid_records,
  invalid_reasons: meta.invalid_reasons,
  field_completeness_pct: fieldCompleteness,
  fields_largely_missing,
  average_completeness_pct: avgCompleteness,
  has_order_summary: !!order_summary,
  analysis_confidence: confidence,
  stage_failures: []
};

return [{ json: { records, order_summary, data_quality } }];

const { records, order_summary, data_quality } = $json;

// ---- Configurable thresholds ----
const MIN_SAMPLE = 10; // minimum segment size before we call something a pattern
const ESTIMATED_HANDLING_COST_INR = 220; // fallback ONLY when no real cost fields exist - always labeled "estimated"
const HOTSPOT_UPLIFT_THRESHOLD = 1.5; // segment ratio must be >=1.5x baseline to flag as a hotspot

function safeDiv(n, d) { return d > 0 ? n / d : null; }
function pct(x) { return x === null ? null : Math.round(x * 1000) / 10; }
function sum(arr, field) { return arr.reduce((s, r) => s + (r[field] || 0), 0); }

const returned = records.filter(r => r.journey_outcome === 'returned');
const rto = records.filter(r => r.journey_outcome === 'rto');
const delivered = records.filter(r => r.journey_outcome === 'delivered');
const cancelled = records.filter(r => r.journey_outcome === 'cancelled');
const unknown = records.filter(r => r.journey_outcome === 'unknown');

const return_value = sum(returned, 'order_value');
const rto_value = sum(rto, 'order_value');
const affected_order_value = return_value + rto_value;

// ---- Actual vs estimated cost (never fake precision) ----
const hasRefundData = records.some(r => r.refund_amount !== null);
const hasShippingCostData = records.some(r => r.forward_shipping_cost !== null || r.return_shipping_cost !== null);
const failed = returned.concat(rto);

const actual_cost_inr = (hasRefundData || hasShippingCostData)
  ? sum(failed, 'refund_amount') + sum(failed, 'forward_shipping_cost') + sum(failed, 'return_shipping_cost')
  : null;

const estimated_cost_inr = actual_cost_inr === null
  ? failed.length * ESTIMATED_HANDLING_COST_INR
  : null;

// ---- True rates - only possible with an order_summary denominator ----
let rateBlock = {
  rates_available: false,
  note: 'order_summary (total_shipped_orders / total_delivered_orders) was not supplied, so true return/RTO rates cannot be computed. Showing event counts and within-dataset shares instead - do not read these as % of all shipped orders.'
};

if (order_summary && order_summary.total_shipped_orders) {
  const shipped = order_summary.total_shipped_orders;
  const deliveredBase = order_summary.total_delivered_orders || null;
  rateBlock = {
    rates_available: true,
    return_rate_pct: deliveredBase ? pct(safeDiv(returned.length, deliveredBase)) : null,
    rto_rate_pct: pct(safeDiv(rto.length, shipped)),
    overall_failure_rate_pct: pct(safeDiv(returned.length + rto.length, shipped))
  };
  if (order_summary.cod_shipped_orders) {
    const codRto = rto.filter(r => r.payment_method === 'COD').length;
    rateBlock.cod_rto_rate_pct = pct(safeDiv(codRto, order_summary.cod_shipped_orders));
  }
  if (order_summary.prepaid_shipped_orders) {
    const prepaidRto = rto.filter(r => r.payment_method === 'Prepaid').length;
    rateBlock.prepaid_rto_rate_pct = pct(safeDiv(prepaidRto, order_summary.prepaid_shipped_orders));
  }
}

// ---- Within-dataset segment analysis (always available, no denominator needed) ----
const overallEvents = returned.length + rto.length;
const overallRtoShare = safeDiv(rto.length, overallEvents);

function buildDimension(dimension, keyFn) {
  const groups = {};
  records.forEach(r => {
    if (r.journey_outcome !== 'returned' && r.journey_outcome !== 'rto') return;
    const key = keyFn(r);
    if (!groups[key]) groups[key] = [];
    groups[key].push(r);
  });

  return Object.entries(groups).map(([value, items]) => {
    const segReturned = items.filter(r => r.journey_outcome === 'returned').length;
    const segRto = items.filter(r => r.journey_outcome === 'rto').length;
    const segEvents = items.length;
    const segRtoShare = safeDiv(segRto, segEvents);
    const uplift = (segRtoShare !== null && overallRtoShare) ? segRtoShare / overallRtoShare : null;
    const sufficientEvidence = segEvents >= MIN_SAMPLE;

    let status = 'normal';
    if (uplift !== null && uplift >= HOTSPOT_UPLIFT_THRESHOLD) {
      status = sufficientEvidence ? 'hotspot_sufficient_evidence' : 'hotspot_hypothesis_insufficient_sample';
    }

    return {
      dimension,
      value,
      returned_count: segReturned,
      rto_count: segRto,
      count: segEvents,
      order_value_lost_inr: sum(items, 'order_value'),
      rto_share_within_segment_pct: pct(segRtoShare),
      overall_rto_share_pct: pct(overallRtoShare),
      uplift_vs_baseline: uplift !== null ? Math.round(uplift * 100) / 100 : null,
      sufficient_evidence: sufficientEvidence,
      status
    };
  }).sort((a, b) => b.count - a.count);
}

const bySku = buildDimension('sku', r => r.sku);
const byCourier = buildDimension('courier', r => r.courier);
const byPincode = buildDimension('pincode', r => r.pincode);
const byZone = buildDimension('zone', r => r.shipping_zone);
const byCategory = buildDimension('category', r => r.product_category);
const byPayment = buildDimension('payment_method', r => r.payment_method);

// ---- COD vs Prepaid, within dataset ----
const codEvents = records.filter(r => r.payment_method === 'COD' && (r.journey_outcome === 'returned' || r.journey_outcome === 'rto'));
const prepaidEvents = records.filter(r => r.payment_method === 'Prepaid' && (r.journey_outcome === 'returned' || r.journey_outcome === 'rto'));
const codRtoShareWithin = safeDiv(codEvents.filter(r => r.journey_outcome === 'rto').length, codEvents.length);
const prepaidRtoShareWithin = safeDiv(prepaidEvents.filter(r => r.journey_outcome === 'rto').length, prepaidEvents.length);

// ---- Time trend (only if order_date present on enough records) ----
let timeTrend = { available: false, note: 'order_date missing on most records - trend analysis skipped.' };
const datedEvents = records.filter(r => r.order_date && (r.journey_outcome === 'returned' || r.journey_outcome === 'rto'));
if (datedEvents.length >= MIN_SAMPLE * 2) {
  const byWeek = {};
  datedEvents.forEach(r => {
    const d = new Date(r.order_date);
    if (isNaN(d.getTime())) return;
    const weekStart = new Date(d);
    weekStart.setDate(d.getDate() - d.getDay());
    const key = weekStart.toISOString().slice(0, 10);
    if (!byWeek[key]) byWeek[key] = { returned: 0, rto: 0, total: 0 };
    byWeek[key].total += 1;
    if (r.journey_outcome === 'rto') byWeek[key].rto += 1; else byWeek[key].returned += 1;
  });
  const weeks = Object.keys(byWeek).sort();
  if (weeks.length >= 2) {
    const last = byWeek[weeks[weeks.length - 1]];
    const prev = byWeek[weeks[weeks.length - 2]];
    const lastRtoShare = safeDiv(last.rto, last.total);
    const prevRtoShare = safeDiv(prev.rto, prev.total);
    timeTrend = {
      available: true,
      weeks_observed: weeks.length,
      latest_week: weeks[weeks.length - 1],
      previous_week: weeks[weeks.length - 2],
      previous_rto_share_pct: pct(prevRtoShare),
      latest_rto_share_pct: pct(lastRtoShare),
      direction: (lastRtoShare !== null && prevRtoShare !== null)
        ? (lastRtoShare > prevRtoShare * 1.2 ? 'increasing' : (lastRtoShare < prevRtoShare * 0.8 ? 'decreasing' : 'stable'))
        : 'insufficient data',
      sufficient_evidence: last.total >= MIN_SAMPLE && prev.total >= MIN_SAMPLE
    };
  }
}

const analytics = {
  counts: {
    total_records: records.length,
    returned_count: returned.length,
    rto_count: rto.length,
    delivered_count: delivered.length,
    cancelled_count: cancelled.length,
    unknown_count: unknown.length
  },
  financial: {
    return_value_inr: return_value,
    rto_value_inr: rto_value,
    affected_order_value_inr: affected_order_value,
    actual_cost_inr,
    estimated_cost_inr,
    cost_basis: actual_cost_inr !== null
      ? 'ACTUAL (refund_amount + shipping costs supplied)'
      : ('ESTIMATED (flat Rs ' + ESTIMATED_HANDLING_COST_INR + '/event - no real cost fields supplied)')
  },
  rates: rateBlock,
  cod_vs_prepaid: {
    cod_rto_share_within_cod_pct: pct(codRtoShareWithin),
    prepaid_rto_share_within_prepaid_pct: pct(prepaidRtoShareWithin),
    cod_sample_size: codEvents.length,
    prepaid_sample_size: prepaidEvents.length,
    sufficient_evidence: codEvents.length >= MIN_SAMPLE && prepaidEvents.length >= MIN_SAMPLE
  },
  segments: {
    sku: bySku.slice(0, 15),
    courier: byCourier.slice(0, 15),
    pincode: byPincode.slice(0, 15),
    zone: byZone,
    category: byCategory,
    payment_method: byPayment
  },
  time_trend: timeTrend,
  min_sample_threshold: MIN_SAMPLE,
  hotspot_uplift_threshold: HOTSPOT_UPLIFT_THRESHOLD
};

return [{ json: { records, analytics, data_quality } }];

const { records, analytics, data_quality, change_since_last_analysis } = $json;

const records_to_classify = records
  .filter(r => r.journey_outcome === 'returned' || r.journey_outcome === 'rto')
  .map(r => ({
    order_id: r.order_id,
    journey_outcome: r.journey_outcome,
    sku: r.sku,
    product_category: r.product_category,
    return_reason_raw: r.return_reason_raw,
    rto_reason_raw: r.rto_reason_raw,
    customer_comment: r.customer_comment
  }));
// Note: only order_id/sku/category/reason text is sent onward to the LLM -
// no phone, email, address or other PII ever leaves this node.

return [{ json: { records, analytics, data_quality, change_since_last_analysis, records_to_classify } }];

const { records, analytics, data_quality, change_since_last_analysis, records_to_classify } =
  $('Select Records To Classify').first().json;

const rawAgentItem = $input.first().json;
const classifierFailed = !!rawAgentItem.error;
const agentOutput = rawAgentItem.output || rawAgentItem;
const classifications = agentOutput.classifications || [];

if (classifierFailed) {
  data_quality.stage_failures = (data_quality.stage_failures || []).concat([
    'Reason Classifier agent failed after retries - all return/RTO records in this run fall back to "Other / Unclear" until the next run.'
  ]);
}

const byOrderId = {};
classifications.forEach(c => { byOrderId[c.order_id] = c; });

const recordsByOrderId = {};
records.forEach(r => { recordsByOrderId[r.order_id] = r; });

const categoryCounts = { returned: {}, rto: {} };

records_to_classify.forEach(rc => {
  const cls = byOrderId[rc.order_id];
  const outcome = rc.journey_outcome;
  const category = (cls && cls.category) ? cls.category : 'Other / Unclear';
  const fullRecord = recordsByOrderId[rc.order_id];
  const value = fullRecord ? fullRecord.order_value : 0;

  if (!categoryCounts[outcome][category]) {
    categoryCounts[outcome][category] = { count: 0, order_value_lost_inr: 0, sample_order_ids: [] };
  }
  categoryCounts[outcome][category].count += 1;
  categoryCounts[outcome][category].order_value_lost_inr += value;
  if (categoryCounts[outcome][category].sample_order_ids.length < 5) {
    categoryCounts[outcome][category].sample_order_ids.push(rc.order_id);
  }
});

const MIN_SAMPLE = analytics.min_sample_threshold;

function toSortedArray(obj) {
  return Object.entries(obj)
    .map(([category, v]) => ({
      category,
      count: v.count,
      order_value_lost_inr: v.order_value_lost_inr,
      sufficient_evidence: v.count >= MIN_SAMPLE,
      sample_order_ids: v.sample_order_ids
    }))
    .sort((a, b) => b.count - a.count);
}

const reason_analysis = {
  return_categories: toSortedArray(categoryCounts.returned),
  rto_categories: toSortedArray(categoryCounts.rto),
  unclassified_count: records_to_classify.length - classifications.length
};

return [{ json: { analytics, reason_analysis, data_quality, change_since_last_analysis } }];

const { analytics, reason_analysis, data_quality, change_since_last_analysis } = $json;

function hotspotsOnly(list) {
  return list.filter(s => s.status && s.status.startsWith('hotspot'));
}

const synthesis_input = {
  totals: analytics.counts,
  financial: analytics.financial,
  rates: analytics.rates,
  cod_vs_prepaid: analytics.cod_vs_prepaid,
  time_trend: analytics.time_trend,
  change_since_last_analysis,
  hotspots: {
    sku: hotspotsOnly(analytics.segments.sku),
    courier: hotspotsOnly(analytics.segments.courier),
    pincode: hotspotsOnly(analytics.segments.pincode),
    zone: hotspotsOnly(analytics.segments.zone),
    category: hotspotsOnly(analytics.segments.category),
    payment_method: hotspotsOnly(analytics.segments.payment_method)
  },
  reason_analysis,
  min_sample_threshold: analytics.min_sample_threshold,
  analysis_confidence: data_quality.analysis_confidence
};

return [{ json: { analytics, reason_analysis, data_quality, change_since_last_analysis, synthesis_input } }];

const { analytics, reason_analysis, data_quality, change_since_last_analysis } =
  $('Prepare Synthesis Input').first().json;

const rawAgentItem = $input.first().json;
const synthesizerFailed = !!rawAgentItem.error;
const agentOutput = rawAgentItem.output || rawAgentItem;
const rootCauses = agentOutput.root_causes || [];

if (synthesizerFailed) {
  data_quality.stage_failures = (data_quality.stage_failures || []).concat([
    'Root-Cause Synthesizer agent failed after retries - no root causes or hypotheses could be produced this run. Deterministic hotspot/anomaly numbers below are still fully valid and computed independently of this failure.'
  ]);
}

const ALL_SEGMENTS = [].concat(
  analytics.segments.sku, analytics.segments.courier, analytics.segments.pincode,
  analytics.segments.zone, analytics.segments.category, analytics.segments.payment_method
);

function findSegment(dimension, value) {
  return ALL_SEGMENTS.find(s => s.dimension === dimension && s.value === value) || null;
}
function findReasonCategory(value) {
  return [...reason_analysis.return_categories, ...reason_analysis.rto_categories]
    .find(c => c.category === value) || null;
}

const CONFIDENCE_WEIGHT = { high: 1, medium: 0.6, low: 0.3 };

const values = rootCauses.map(rc => {
  const seg = rc.dimension === 'reason' ? findReasonCategory(rc.segment_value) : findSegment(rc.dimension, rc.segment_value);
  return seg ? (seg.order_value_lost_inr || 0) : 0;
});
const maxValue = Math.max(1, ...values, 0);

const scored = rootCauses.map(rc => {
  const seg = rc.dimension === 'reason' ? findReasonCategory(rc.segment_value) : findSegment(rc.dimension, rc.segment_value);
  const value = seg ? (seg.order_value_lost_inr || 0) : 0;
  const count = seg ? (seg.count || 0) : 0;
  const uplift = (seg && seg.uplift_vs_baseline) ? Math.min(seg.uplift_vs_baseline, 5) / 5 : 0.3;
  const confidenceWeight = CONFIDENCE_WEIGHT[rc.confidence] || 0.3;
  const sufficientEvidence = seg ? !!seg.sufficient_evidence : (rc.status === 'confirmed_pattern');

  const impact_component = value / maxValue;
  const priority_score = Math.round((impact_component * 0.45 + uplift * 0.25 + confidenceWeight * 0.30) * 100) / 100;

  let priority_tier = 'P3';
  if (sufficientEvidence && priority_score >= 0.7) priority_tier = 'P0';
  else if (sufficientEvidence && priority_score >= 0.5) priority_tier = 'P1';
  else if (priority_score >= 0.3) priority_tier = 'P2';

  // v3: segment_matched marks whether this root cause could actually be re-joined
  // to a real deterministic segment. The Self-Verification Engine treats an
  // unmatched segment as an unverified claim regardless of what the model said.
  return Object.assign({}, rc, {
    order_count: count,
    order_value_lost_inr: value,
    uplift_vs_baseline: seg ? seg.uplift_vs_baseline : null,
    sufficient_evidence: sufficientEvidence,
    segment_matched: !!seg,
    priority_score,
    priority_tier
  });
});

scored.sort((a, b) => b.priority_score - a.priority_score);
const top_problems = scored.slice(0, 5).map((rc, i) => Object.assign({ rank: i + 1 }, rc));

return [{ json: { analytics, reason_analysis, data_quality, change_since_last_analysis, root_causes: scored, top_problems } }];

const {
  analytics, reason_analysis, data_quality, change_since_last_analysis,
  root_causes, top_problems, recommendations, hypotheses, verification
} = $('Self-Verification Engine').first().json;

const PRIORITY_ORDER = { P0: 0, P1: 1, P2: 2, P3: 3 };
const sortedRecommendations = (recommendations || [])
  .slice()
  .sort((a, b) => (PRIORITY_ORDER[a.priority] ?? 9) - (PRIORITY_ORDER[b.priority] ?? 9));

const data_gaps = [];
if (!analytics.rates.rates_available) {
  data_gaps.push('No order_summary supplied - return_rate/rto_rate could not be computed against total shipped orders; segment metrics are shares within the returns/RTO dataset only.');
}
if (analytics.financial.actual_cost_inr === null) {
  data_gaps.push('No refund_amount/shipping cost fields supplied - cost figures are ESTIMATED, not actual.');
}
if (!analytics.time_trend.available) {
  data_gaps.push(analytics.time_trend.note);
}
if (data_quality.fields_largely_missing && data_quality.fields_largely_missing.length) {
  data_gaps.push('Sparsely populated fields (<20% of records): ' + data_quality.fields_largely_missing.join(', '));
}
if (!sortedRecommendations.length) {
  data_gaps.push('No prioritized problems met the criteria for a recommendation this run.');
}
if (data_quality.input_truncated) {
  data_gaps.push('Input exceeded ' + data_quality.max_rows_cap + ' rows and was truncated to the first ' + data_quality.max_rows_cap + ' - results reflect a partial dataset.');
}
if (data_quality.stage_failures && data_quality.stage_failures.length) {
  data_gaps.push.apply(data_gaps, data_quality.stage_failures);
}
if (!change_since_last_analysis || !change_since_last_analysis.available) {
  data_gaps.push((change_since_last_analysis && change_since_last_analysis.note) || 'No prior run available for trend comparison yet.');
}

// Deterministic, data-grounded suggestions for the conversational follow-up
// endpoint (spec section 24) - not asked of the LLM, generated from the same
// numbers already in this response so they can never reference a problem
// that doesn't exist.
const next_best_questions = [];
if (top_problems[0]) {
  next_best_questions.push('Why is ' + top_problems[0].dimension + ' "' + top_problems[0].segment_value + '" our biggest problem right now?');
}
if (sortedRecommendations[0]) {
  next_best_questions.push('What evidence supports the recommendation for "' + sortedRecommendations[0].target + '"?');
}
if (analytics.cod_vs_prepaid && analytics.cod_vs_prepaid.sufficient_evidence) {
  next_best_questions.push('Is COD actually driving our RTO more than prepaid?');
}
if (change_since_last_analysis && change_since_last_analysis.available) {
  next_best_questions.push('What changed since the last analysis?');
}
next_best_questions.push('Which action has the highest expected impact for the effort involved?');

const response = {
  product: 'ReturnShield AI',
  run: {
    id: data_quality.run_id,
    generated_at: new Date().toISOString(),
    status: (data_quality.stage_failures && data_quality.stage_failures.length) ? 'partial' : 'success'
  },
  analysis: {
    generated_at: new Date().toISOString(),
    records_analyzed: analytics.counts.total_records,
    analysis_confidence: data_quality.analysis_confidence,
    run_id: data_quality.run_id
  },
  metrics: {
    returned_orders: analytics.counts.returned_count,
    rto_orders: analytics.counts.rto_count,
    delivered_orders: analytics.counts.delivered_count,
    cancelled_orders: analytics.counts.cancelled_count,
    return_value_inr: analytics.financial.return_value_inr,
    rto_value_inr: analytics.financial.rto_value_inr,
    affected_order_value_inr: analytics.financial.affected_order_value_inr,
    actual_cost_inr: analytics.financial.actual_cost_inr,
    estimated_cost_inr: analytics.financial.estimated_cost_inr,
    cost_basis: analytics.financial.cost_basis,
    rates: analytics.rates
  },
  cod_vs_prepaid: analytics.cod_vs_prepaid,
  segments: analytics.segments,
  reason_analysis,
  time_trend: analytics.time_trend,
  trends: change_since_last_analysis ? [change_since_last_analysis] : [],
  top_problems,
  root_causes,
  hypotheses,
  recommendations: sortedRecommendations,
  verification,
  data_quality,
  data_gaps,
  next_best_questions
};

return [{ json: response }];

// NEW in v3 - "What changed since the last analysis?" (spec section 24)
// Uses n8n's built-in workflow static data - persists across executions of THIS workflow
// on THIS n8n instance, with zero external DB and zero credentials to configure.
// This is read-only here; the matching write happens in "Record Run In Memory" at the
// end of the pipeline, once top_problems/recommendations actually exist.

const { records, analytics, data_quality } = $json;

const staticData = $getWorkflowStaticData('global');
const history = Array.isArray(staticData.previous_runs) ? staticData.previous_runs : [];
const previous = history.length ? history[history.length - 1] : null;

function deltaPct(curr, prev) {
  if (!prev) return null;
  return Math.round(((curr - prev) / prev) * 1000) / 10;
}

let change_since_last_analysis;
if (!previous) {
  change_since_last_analysis = {
    available: false,
    note: 'No previous run found in this workflow\'s memory yet - this is either the first run, or workflow static data was reset. Trend comparison will be available starting next run.'
  };
} else {
  change_since_last_analysis = {
    available: true,
    compared_to_run_id: previous.run_id,
    compared_to_generated_at: previous.generated_at,
    returned_count_change: analytics.counts.returned_count - previous.returned_count,
    rto_count_change: analytics.counts.rto_count - previous.rto_count,
    affected_order_value_change_inr: analytics.financial.affected_order_value_inr - previous.affected_order_value_inr,
    affected_order_value_change_pct: deltaPct(analytics.financial.affected_order_value_inr, previous.affected_order_value_inr),
    previous_top_problem: previous.top_problem || null,
    note: 'Comparison is against the most recent prior run recorded by this workflow instance.'
  };
}

return [{ json: { records, analytics, data_quality, change_since_last_analysis } }];

// NEW in v3 - deterministic self-verification stage (spec section 20) plus
// human-in-the-loop flagging for consequential actions (spec section 16).
// This node NEVER trusts the LLM's own confidence claims - it re-derives what
// it can from the deterministic numbers already computed upstream, and
// repairs/downgrades anything it can't verify rather than passing it through.

const prior = $('Priority & Impact Engine').first().json;
const { analytics, reason_analysis, data_quality, change_since_last_analysis } = prior;
let root_causes = prior.root_causes || [];
let top_problems = prior.top_problems || [];

const rawAgentItem = $input.first().json;
const recAgentFailed = !!rawAgentItem.error;
const agentOutput = rawAgentItem.output || rawAgentItem;
let recommendations = agentOutput.recommendations || [];

const issues = [];
const corrections = [];

if (recAgentFailed) {
  data_quality.stage_failures = (data_quality.stage_failures || []).concat([
    'Recommendation Agent failed after retries - no recommendations could be generated this run. top_problems/root_causes below are unaffected.'
  ]);
  issues.push('Recommendation Agent call failed after retries - recommendations list is empty this run.');
}

// ---- Check 1+2: every recommendation must trace to a real, scored problem,
// and its confidence can never exceed what the underlying evidence supports. ----
recommendations = recommendations.map(rec => {
  const matched = top_problems.find(p =>
    rec.target && p.segment_value && rec.target.toLowerCase().includes(String(p.segment_value).toLowerCase())
  );

  if (!matched) {
    issues.push('Recommendation targeting "' + (rec.target || 'unknown target') + '" could not be traced back to a scored problem - confidence capped and flagged unverified.');
    corrections.push({ field: 'confidence', target: rec.target || null, from: rec.confidence, to: Math.min(rec.confidence || 0.3, 0.3) });
    return Object.assign({}, rec, { confidence: Math.min(rec.confidence || 0.3, 0.3), unverified_target: true });
  }

  const cap = matched.sufficient_evidence ? 1 : 0.5;
  if ((rec.confidence || 0) > cap) {
    corrections.push({ field: 'confidence', target: rec.target, from: rec.confidence, to: cap });
    return Object.assign({}, rec, { confidence: cap, unverified_target: false });
  }
  return Object.assign({}, rec, { unverified_target: false });
});

// ---- Check 3: root-cause confidence label must match the deterministic
// sufficient_evidence flag computed in Priority & Impact Engine. ----
root_causes = root_causes.map(rc => {
  if (rc.sufficient_evidence === false && rc.confidence === 'high') {
    issues.push('Root cause for "' + rc.segment_value + '" claimed high confidence without sufficient evidence - downgraded to low.');
    corrections.push({ field: 'confidence', target: rc.segment_value, from: 'high', to: 'low' });
    return Object.assign({}, rc, { confidence: 'low', status: 'hypothesis' });
  }
  if (rc.segment_matched === false) {
    issues.push('Root cause referenced segment "' + rc.segment_value + '" which could not be found in the deterministic analytics - marked unverified.');
    return Object.assign({}, rc, { unverified_segment: true });
  }
  return rc;
});

// ---- Check 4: required-field presence (schema sanity) ----
const REQUIRED_REC_FIELDS = ['priority', 'action', 'target', 'reason', 'evidence', 'expected_metric', 'effort', 'confidence'];
recommendations.forEach(rec => {
  REQUIRED_REC_FIELDS.forEach(f => {
    if (rec[f] === undefined || rec[f] === null || rec[f] === '') {
      issues.push('Recommendation for "' + (rec.target || 'unknown target') + '" is missing required field "' + f + '".');
    }
  });
});

// ---- Check 5: human-in-the-loop flagging (spec section 16) ----
// Deterministic keyword match, NOT left to the LLM's own judgment - an action
// is flagged for approval based on what it actually touches, not on how the
// model chose to describe its own risk level.
const CONSEQUENTIAL_PATTERNS = [
  { rx: /cod eligib|disable cod|remove cod/i, reason: 'Changes COD eligibility for customers.' },
  { rx: /block(ing)?\s+(the\s+)?customer|blacklist/i, reason: 'Blocks or blacklists customers.' },
  { rx: /courier reassign|switch courier|change courier|drop courier/i, reason: 'Changes live courier routing.' },
  { rx: /message (the )?customer|whatsapp|sms|email campaign|notify customers/i, reason: 'Sends direct customer communication.' },
  { rx: /\brefund\b|discount|price change|waive/i, reason: 'Affects customer-facing pricing or refunds.' }
];
recommendations = recommendations.map(rec => {
  const text = (rec.action || '') + ' ' + (rec.target || '');
  const hit = CONSEQUENTIAL_PATTERNS.find(p => p.rx.test(text));
  return Object.assign({}, rec, {
    requires_human_approval: !!hit,
    approval_reason: hit ? hit.reason + ' Route through human approval before execution (see Section 16 / Record Feedback workflow).' : null
  });
});

// ---- Assemble hypotheses (spec section 11) surfaced as a flat top-level list ----
const hypotheses = root_causes.flatMap(rc =>
  (rc.hypotheses || []).map(h => Object.assign({
    source_problem: rc.problem,
    dimension: rc.dimension,
    segment_value: rc.segment_value
  }, h))
);

const verification = {
  checks_performed: [
    'recommendation_target_traceability',
    'recommendation_confidence_vs_evidence_cap',
    'root_cause_confidence_vs_sufficient_evidence',
    'root_cause_segment_traceability',
    'required_field_presence',
    'consequential_action_flagging'
  ],
  issues_found: issues,
  corrections_applied: corrections,
  status: issues.length === 0 ? 'passed' : 'passed_with_corrections'
};

return [{
  json: {
    analytics, reason_analysis, data_quality, change_since_last_analysis,
    root_causes, top_problems, recommendations, hypotheses, verification
  }
}];

// NEW in v3 - "Learn / store state" (spec section 19). Writes the outcome of
// THIS run into workflow static data so the NEXT run's "Compute Trend Delta"
// node can answer "what changed since the last analysis?". Runs in parallel
// with Respond to Webhook, so it can never delay or block the response.

const response = $json;
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.previous_runs)) staticData.previous_runs = [];

staticData.previous_runs.push({
  run_id: response.run.id,
  generated_at: response.run.generated_at,
  returned_count: response.metrics.returned_orders,
  rto_count: response.metrics.rto_orders,
  affected_order_value_inr: response.metrics.affected_order_value_inr,
  top_problem: response.top_problems && response.top_problems[0] ? response.top_problems[0].problem : null,
  analysis_confidence: response.analysis.analysis_confidence
});

// Keep only the most recent 20 runs so static data doesn't grow unbounded.
if (staticData.previous_runs.length > 20) {
  staticData.previous_runs = staticData.previous_runs.slice(-20);
}

return [{ json: { stored: true, run_id: response.run.id, history_length: staticData.previous_runs.length } }];

// Inbound Webhook Authentication Gate
const headers = $input.first().json.headers || {};
const authHeader = String(headers['authorization'] || headers['Authorization'] || '');
const secretHeader = String(headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '');
const incomingSecret = secretHeader || (authHeader.startsWith('Bearer ') ? authHeader.slice(7).trim() : '');
const EXPECTED_SECRET = ($env && $env.N8N_WEBHOOK_SECRET) ? $env.N8N_WEBHOOK_SECRET : '';
const authorized = !EXPECTED_SECRET || (incomingSecret === EXPECTED_SECRET);

return [{
  json: {
    ...$input.first().json,
    _auth: {
      authorized,
      error: authorized ? null : 'Unauthorized: Missing or invalid X-Webhook-Secret header.'
    }
  }
}];

parameters.responseBody:
{
  "error": true,
  "status": 401,
  "message": "Unauthorized: Missing or invalid X-Webhook-Secret header."
}
